export const structuralKnowledgePoints: StructuralKnowledgePoint[] = seeds.map(([
  level,
  group,
  id,
  title,
  description,
  prerequisites,
  core,
  formula,
  engineering,
  pitfall,
  check,
  question,
]) => ({
  level,
  group,
  id,
  title,
  description,
  prerequisites,
  core,
  formula,
  engineering,
  pitfall,
  check,
  question,
}));

export const structuralLevelLabels: Record<StructuralLearningLevel, string> = {
  low: '初级',
  mid: '中级',
  high: '高级',
};

export const structuralPlans = {
  low: structuralKnowledgePoints.filter((point) => point.level === 'low'),
  mid: structuralKnowledgePoints.filter((point) => point.level === 'mid'),
  high: structuralKnowledgePoints.filter((point) => point.level === 'high'),
};

export function getStructuralKnowledgePoint(id: string): StructuralKnowledgePoint | undefined {
  return structuralKnowledgePoints.find((point) => point.id === id);
}

export function structuralKnowledgeMarkdown(point: StructuralKnowledgePoint): string {
  return `## 核心概念

${point.core}

## 关键公式

${point.formula}

公式应结合本页所列假设与适用边界使用，不能脱离单位制、坐标系和载荷条件单独解释。

## 工程意义

${point.engineering}

## 常见误区

- ${point.pitfall}
- 只保存最终结果，没有记录输入来源、提取位置和适用范围。

## 验证清单

- ${point.check}
- 用至少一种独立方法检查数量级、守恒关系或趋势。
- 在结论中明确模型假设、误差来源与需要人工复核的事项。`;
}
